insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'combinatorics' and track_id = (select id from tracks where slug = 'amc-8')), 'Counting Principles', 'counting-principles', '[{"type":"meta","author":"Benjamin Qi","frequency":"essential"},{"type":"section","title":"Introduction"},{"type":"text","content":"Most counting problems reduce to two ideas: when do we **multiply**, and when do we **add**? Getting this right is the whole game on the AMC 8."},{"type":"section","title":"The Multiplication Principle"},{"type":"text","content":"If a task splits into a sequence of independent stages, with $a$ choices for the first stage, $b$ for the second, and so on, then the number of ways to complete the whole task is the **product**\n$$a \\times b \\times \\cdots.$$\n\n**Example.** An ice-cream shop has $4$ flavors and $3$ toppings. A scoop-with-topping can be made in\n$$4 \\times 3 = 12$$\nways, because each of the $4$ flavors pairs with each of the $3$ toppings."},{"type":"section","title":"The Addition Principle"},{"type":"text","content":"If a task can be done in one of several **mutually exclusive** ways — cases that never overlap — then the total count is the **sum** of the counts of each case.\n\n**Example.** To travel from $A$ to $B$ you may take one of $3$ bus routes **or** one of $2$ train routes. Since you pick exactly one mode, there are\n$$3 + 2 = 5$$\nways. We add because the bus and train options do not overlap.\n\nThe guiding question: *are the options happening together (multiply) or instead of each other (add)?*"},{"type":"resource","source":"CPH","stars":4,"title":"Counting — Competitive Programmer''s Handbook","description":"A crisp treatment of the multiplication and addition rules with worked examples.","url":"https://cses.fi/book/book.pdf"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"License plates","source":"AMC 8 (practice)","difficulty":"Easy","statement":"A license plate has $2$ letters (A–Z) followed by $3$ digits (0–9), with repeats allowed. How many different plates are possible?","hint":"Each position is an independent stage — multiply the number of choices.","solution":"There are $26$ choices for each letter and $10$ for each digit:\n$$26 \\times 26 \\times 10 \\times 10 \\times 10 = 676 \\times 1000 = 676{,}000.$$"},{"type":"problem","title":"Paths on a grid","source":"AMC 8 (practice)","difficulty":"Medium","statement":"Starting at the bottom-left corner of a $3 \\times 3$ grid of streets, you walk to the top-right corner moving only **right** or **up**. How many shortest paths are there?","hint":"Every shortest path is a rearrangement of $3$ R''s and $3$ U''s. Count the arrangements.","solution":"A path is a sequence of $3$ rights and $3$ ups, so we choose which $3$ of the $6$ steps are \"right\":\n$$\\binom{6}{3} = \\frac{6!}{3!\\,3!} = 20.$$"},{"type":"problem","title":"At least one even","source":"AMC 8 (practice)","difficulty":"Medium","statement":"A three-digit code uses digits $1$ through $6$, repeats allowed. How many codes contain **at least one** even digit?","hint":"Complementary counting: total minus the codes with **no** even digit.","solution":"There are $6^3 = 216$ codes in all. Codes using only the odd digits $\\{1,3,5\\}$ number $3^3 = 27$. So the codes with at least one even digit total\n$$216 - 27 = 189.$$"}]'::jsonb, 0)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'combinatorics' and track_id = (select id from tracks where slug = 'amc-8')), 'Counting Methods', 'counting-methods', '[{"type":"meta","author":"SFMA","frequency":"essential"},{"type":"section","title":"The Fundamental Counting Principle"},{"type":"text","content":"Most counting problems reduce to two ideas: **multiply** when choices are made together (\"and\"), and **add** when choices are alternatives (\"or\").\n\n- **Multiplication Principle.** If task $A$ can be done in $m$ ways and task $B$ in $n$ ways independently, then doing $A$ **and then** $B$ can be done in $m \\times n$ ways.\n- **Addition Principle.** If $A$ can be done in $m$ ways and $B$ in $n$ ways, and the two are **mutually exclusive**, then doing $A$ **or** $B$ can be done in $m + n$ ways."},{"type":"text","content":"### The slot-filling strategy\n\nImagine filling a sequence of labeled slots one at a time. For each slot ask: *how many choices remain, given what''s already chosen?* Then multiply across the slots. If the problem breaks into separate scenarios, count each and add.\n\nBefore every calculation, say it out loud: **\"AND or OR?\"** Multiplying when you should add (and vice versa) is the most common counting mistake."},{"type":"section","title":"Examples — Counting Principle"},{"type":"problem","title":"Combo meals","source":"AMC 8 Course","difficulty":"Easy","statement":"A café offers $4$ sandwiches, $3$ soups, and $2$ drinks. A combo is one of each. How many different combos are possible?","hint":"One choice \"and\" another \"and\" another — multiply.","solution":"$$4 \\times 3 \\times 2 = 24.$$"},{"type":"problem","title":"License plates","source":"AMC 8 Course","difficulty":"Easy","statement":"A plate is $3$ letters (A–Z) followed by $3$ digits (0–9), repeats allowed. How many plates are possible?","hint":"Each position is an independent slot.","solution":"$$26^3 \\times 10^3 = 17576 \\times 1000 = 17{,}576{,}000.$$"},{"type":"problem","title":"All digits different","source":"AMC 8 Course","difficulty":"Medium","statement":"How many three-digit numbers (from $100$ to $999$) have all three digits different?","hint":"Fill the hundreds digit first, then tens, then units, tracking remaining choices.","solution":"Hundreds: $9$ choices ($1$–$9$). Tens: $9$ (any digit except the hundreds digit, including $0$). Units: $8$. So\n$$9 \\times 9 \\times 8 = 648.$$"},{"type":"problem","title":"Competition entries","source":"AMC 8 Course","difficulty":"Medium","statement":"A student picks one problem to present from Topic A ($3$ problems) **or** Topic B ($5$ problems), and separately picks one of $4$ worksheets. How many entries (one problem, one worksheet) are possible?","hint":"Add within the problem choice (A or B), then multiply by the worksheet choice.","solution":"There are $3 + 5 = 8$ problem choices and $4$ worksheets, so\n$$(3 + 5) \\times 4 = 32.$$"},{"type":"section","title":"Permutations and Combinations"},{"type":"text","content":"Both count selections from a set — they differ in one question: **does order matter?**\n\n- **Permutations** count **ordered** arrangements:\n$$P(n, r) = \\frac{n!}{(n-r)!} = n(n-1)\\cdots(n-r+1).$$\nArranging all $n$ objects gives $n!$.\n- **Combinations** count **unordered** selections:\n$$\\binom{n}{r} = \\frac{n!}{r!\\,(n-r)!} = \\frac{P(n,r)}{r!}.$$"},{"type":"text","content":"### The central question\n\n> Does the order of the chosen items matter?\n\n\"How many ways can $3$ students **line up**?\" — order matters — **permutation**.\n\"How many ways can $3$ students be **chosen** for a team?\" — order doesn''t — **combination**.\n\nA combination is a permutation with the $r!$ internal arrangements of the chosen group divided out.\n\n**Repeated letters.** Arranging $n$ objects where item $i$ repeats $k_i$ times gives $\\dfrac{n!}{k_1!\\,k_2!\\cdots}$ distinct arrangements — we divide to undo the overcount from swapping identical copies."},{"type":"section","title":"Examples — Permutations"},{"type":"problem","title":"Medals","source":"AMC 8 Course","difficulty":"Easy","statement":"Eight runners race with no ties. In how many ways can gold, silver, and bronze be awarded?","hint":"Order matters — this is $P(8,3)$.","solution":"$$8 \\times 7 \\times 6 = 336.$$"},{"type":"problem","title":"Club offices","source":"AMC 8 Course","difficulty":"Easy","statement":"A club of $10$ members elects a President, Vice President, and Treasurer (all different). How many ways?","hint":"Three distinct ordered roles: $P(10,3)$.","solution":"$$10 \\times 9 \\times 8 = 720.$$"},{"type":"problem","title":"Four-letter strings","source":"AMC 8 Course","difficulty":"Medium","statement":"How many four-letter strings can be formed from the letters of $\\textsf{PROBLEM}$ with no letter repeated?","hint":"$\\textsf{PROBLEM}$ has $7$ distinct letters; arrange $4$ of them in order.","solution":"$$P(7,4) = 7 \\times 6 \\times 5 \\times 4 = 840.$$"},{"type":"problem","title":"Arrangements of LEVEL","source":"AMC 8 Course","difficulty":"Medium","statement":"In how many distinct ways can the letters of $\\textsf{LEVEL}$ be arranged?","hint":"There are repeated letters — divide by the factorials of their counts.","solution":"$\\textsf{LEVEL}$ has $5$ letters with $\\textsf{L}$ twice and $\\textsf{E}$ twice, so\n$$\\frac{5!}{2!\\,2!} = \\frac{120}{4} = 30.$$"},{"type":"section","title":"Examples — Combinations"},{"type":"problem","title":"A committee","source":"AMC 8 Course","difficulty":"Easy","statement":"How many ways can a committee of $3$ be chosen from $12$ students?","hint":"Order doesn''t matter — this is $\\binom{12}{3}$.","solution":"$$\\binom{12}{3} = \\frac{12 \\cdot 11 \\cdot 10}{3 \\cdot 2 \\cdot 1} = 220.$$"},{"type":"problem","title":"Pizza toppings","source":"AMC 8 Course","difficulty":"Easy","statement":"A shop lets you choose exactly $2$ toppings from $8$. How many different pizzas are possible?","hint":"Choosing toppings is unordered: $\\binom{8}{2}$.","solution":"$$\\binom{8}{2} = \\frac{8 \\cdot 7}{2} = 28.$$"},{"type":"problem","title":"Boys and girls","source":"AMC 8 Course","difficulty":"Medium","statement":"A team of $5$ is chosen from $7$ boys and $5$ girls. How many teams have exactly $3$ boys and $2$ girls?","hint":"Choose the boys and the girls separately, then multiply.","solution":"$$\\binom{7}{3}\\binom{5}{2} = 35 \\times 10 = 350.$$"},{"type":"problem","title":"Handshakes","source":"AMC 8 Course","difficulty":"Medium","statement":"At a party of $10$ people, everyone shakes hands with everyone else exactly once. How many handshakes occur?","hint":"Each handshake is a choice of $2$ people from $10$ — and it''s an edge of $K_{10}$.","solution":"$$\\binom{10}{2} = \\frac{10 \\cdot 9}{2} = 45,$$\nwhich is also the number of edges in the complete graph $K_{10}$."},{"type":"section","title":"Casework"},{"type":"text","content":"**Casework** breaks a problem into smaller non-overlapping sub-problems (cases), solves each, and adds. It is a strategy, not a formula. A casework argument is valid only when the cases are:\n\n1. **Mutually exclusive** — no outcome is counted twice.\n2. **Exhaustive** — every outcome lands in some case.\n\nGood things to case on: the value of a single digit, the number of items of a type, parity, or the size of the largest item. And when a condition says \"at least one,\" it is often faster to count the **complement**:\n$$|\\text{desired}| = |\\text{total}| - |\\text{undesired}|.$$"},{"type":"section","title":"Examples — Casework"},{"type":"problem","title":"Digit sum equals 9","source":"AMC 8 Course","difficulty":"Easy","statement":"How many two-digit numbers have digit sum equal to $9$?","hint":"Case on the tens digit; the units digit is forced.","solution":"For tens digit $t \\in \\{1, \\ldots, 9\\}$, the units digit must be $9 - t \\in \\{0, \\ldots, 8\\}$, always a valid digit. That''s one number per $t$:\n$$18, 27, 36, 45, 54, 63, 72, 81, 90 \\ \\Rightarrow\\ 9 \\text{ numbers}.$$"},{"type":"problem","title":"Dice sums","source":"AMC 8 Course","difficulty":"Easy","statement":"Two standard dice are rolled. In how many outcomes is the sum $7$? In how many is the sum $8$?","hint":"List ordered pairs $(a,b)$ for each target sum.","solution":"Sum $7$: $(1,6),(2,5),(3,4),(4,3),(5,2),(6,1)$ — $6$ outcomes. Sum $8$: $(2,6),(3,5),(4,4),(5,3),(6,2)$ — $5$ outcomes."},{"type":"problem","title":"Divisible by 4 or 5, not both","source":"AMC 8 Course","difficulty":"Medium","statement":"How many integers from $1$ to $100$ are divisible by $4$ or $5$ but **not** both?","hint":"Count multiples of $4$, of $5$, and of $20$; then take \"exactly one.\"","solution":"Multiples of $4$: $25$. Of $5$: $20$. Of both (i.e. $20$): $5$. \"Only $4$\" $= 25 - 5 = 20$; \"only $5$\" $= 20 - 5 = 15$. Total $= 20 + 15 = 35$."},{"type":"problem","title":"Exactly two equal digits","source":"AMC 8 Course","difficulty":"Hard","statement":"How many integers from $100$ to $199$ have **exactly two** equal digits?","hint":"Every such number is $\\overline{1XY}$. Case on whether the repeated digit is $1$ or not.","solution":"Write the number as $\\overline{1XY}$.\n\n**Case 1 — the two equal digits are both $1$:** exactly one of $X, Y$ equals $1$ and the other differs. If $X = 1$, then $Y \\neq 1$ gives $9$ values; if $Y = 1$, then $X \\neq 1$ gives $9$. That''s $18$ (and $111$ is excluded since its third digit also equals $1$).\n\n**Case 2 — $X = Y \\neq 1$:** the pair $X = Y$ can be any of $\\{0,2,3,\\ldots,9\\}$, i.e. $9$ values, with the leading $1$ different.\n\nTotal $= 18 + 9 = 27$."},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"Constrained codes","source":"AMC 8 Course","difficulty":"Medium","statement":"How many four-digit codes use digits $1$–$9$ (no zeros), repeats allowed, with the first digit odd and the last digit even?","hint":"Count each slot''s choices and multiply.","solution":"First digit odd: $\\{1,3,5,7,9\\}$, $5$ choices. Last digit even: $\\{2,4,6,8\\}$, $4$ choices. Middle two: $9$ each. So $5 \\cdot 9 \\cdot 9 \\cdot 4 = 1620$."},{"type":"problem","title":"Choosing books","source":"AMC 8 Course","difficulty":"Easy","statement":"From $5$ math books and $4$ science books (all different), how many ways are there to choose $2$ math books and $1$ science book?","hint":"Combinations, multiplied.","solution":"$$\\binom{5}{2}\\binom{4}{1} = 10 \\times 4 = 40.$$"},{"type":"problem","title":"Tallest friends together","source":"AMC 8 Course","difficulty":"Medium","statement":"Eight friends stand in a line for a photo. In how many arrangements are the two tallest **next to each other**?","hint":"Glue the two tall friends into a single block, then account for their internal order.","solution":"Treat the pair as one block: $7$ items arrange in $7! = 5040$ ways, and the block''s two friends can swap in $2! = 2$ ways. Total $7! \\cdot 2! = 10080$."},{"type":"problem","title":"Three-digit even numbers","source":"AMC 8 Course","difficulty":"Medium","statement":"How many three-digit even numbers can be formed from $\\{1,2,3,4,5,6\\}$ with no repeated digit?","hint":"Decide the units digit first.","solution":"Units digit even: $\\{2,4,6\\}$, $3$ choices. Then hundreds: $5$ remaining, tens: $4$ remaining. So $3 \\cdot 5 \\cdot 4 = 60$."},{"type":"problem","title":"At least two girls","source":"AMC 8 Course","difficulty":"Hard","statement":"A committee of $4$ is chosen from $6$ boys and $5$ girls. How many committees contain **at least** $2$ girls?","hint":"Use the complement: total minus (0 girls) minus (1 girl).","solution":"Total committees: $\\binom{11}{4} = 330$. With $0$ girls: $\\binom{6}{4} = 15$. With $1$ girl: $\\binom{5}{1}\\binom{6}{3} = 5 \\cdot 20 = 100$. At least $2$ girls $= 330 - 15 - 100 = 215$."},{"type":"problem","title":"No square digits","source":"AMC 8 Course","difficulty":"Medium","statement":"How many two-digit numbers ($10$–$99$) have **neither** digit a perfect square? (The single-digit perfect squares are $1$, $4$, $9$.)","hint":"The allowed digits are $\\{0,2,3,5,6,7,8\\}$; the tens digit can''t be $0$.","solution":"Allowed digits: $\\{0,2,3,5,6,7,8\\}$ ($7$ of them). Tens digit must be nonzero: $6$ choices. Units digit: $7$ choices. Total $6 \\times 7 = 42$."}]'::jsonb, 1)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

