insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'limits-and-continuity' and track_id = (select id from tracks where slug = 'ap-calculus-bc')), 'Evaluating Limits', 'evaluating-limits', '[{"type":"meta","author":"SFMA Staff","frequency":"essential"},{"type":"section","title":"Introduction"},{"type":"text","content":"A **limit** describes the value a function approaches as its input approaches some point. We write\n$$\\lim_{x \\to a} f(x) = L$$\nto mean that $f(x)$ gets arbitrarily close to $L$ as $x$ gets close to $a$ (from either side). Limits are the foundation on which derivatives and integrals are built."},{"type":"section","title":"Techniques"},{"type":"text","content":"**Direct substitution.** If $f$ is continuous at $a$, then $\\lim_{x\\to a} f(x) = f(a)$. Always try this first.\n\n**Factoring.** When substitution gives the indeterminate form $\\tfrac{0}{0}$, factor and cancel:\n$$\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2} = \\lim_{x \\to 2} \\frac{(x-2)(x+2)}{x-2} = \\lim_{x\\to 2}(x+2) = 4.$$\n\n**L''Hôpital''s Rule.** For a $\\tfrac{0}{0}$ or $\\tfrac{\\infty}{\\infty}$ form,\n$$\\lim_{x\\to a}\\frac{f(x)}{g(x)} = \\lim_{x\\to a}\\frac{f''(x)}{g''(x)},$$\nprovided the right-hand limit exists."},{"type":"resource","source":"Khan Academy","stars":5,"title":"Limits and continuity","description":"Video-based walkthroughs of every limit technique on the AP exam.","url":"https://www.khanacademy.org/math/ap-calculus-bc"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"A removable discontinuity","source":"AP Calculus BC (practice)","difficulty":"Easy","statement":"Evaluate\n$$\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}.$$","hint":"The form is $\\tfrac{0}{0}$. Factor the numerator as a difference of squares.","solution":"Factor and cancel:\n$$\\frac{x^2-9}{x-3} = \\frac{(x-3)(x+3)}{x-3} = x+3.$$\nSo the limit is $3 + 3 = 6.$"},{"type":"problem","title":"A trigonometric limit","source":"AP Calculus BC (practice)","difficulty":"Medium","statement":"Evaluate\n$$\\lim_{x \\to 0} \\frac{\\sin(5x)}{3x}.$$","hint":"Use the standard limit $\\lim_{u\\to 0}\\tfrac{\\sin u}{u} = 1$ after matching the argument.","solution":"Rewrite to expose $\\tfrac{\\sin u}{u}$ with $u = 5x$:\n$$\\frac{\\sin 5x}{3x} = \\frac{5}{3}\\cdot\\frac{\\sin 5x}{5x} \\longrightarrow \\frac{5}{3}\\cdot 1 = \\frac{5}{3}.$$"},{"type":"problem","title":"L''Hôpital''s Rule","source":"AP Calculus BC (practice)","difficulty":"Medium","statement":"Evaluate\n$$\\lim_{x \\to 0} \\frac{e^x - 1 - x}{x^2}.$$","hint":"The form is $\\tfrac{0}{0}$. Apply L''Hôpital''s Rule twice.","solution":"Differentiating top and bottom: $\\tfrac{e^x - 1}{2x}$, still $\\tfrac00$. Again: $\\tfrac{e^x}{2} \\to \\tfrac12$. So the limit is $\\tfrac{1}{2}.$"}]'::jsonb, 0)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

