insert into lessons (module_id, title, slug, content, order_index)
values ((select id from modules where slug = 'integration' and track_id = (select id from tracks where slug = 'ap-calculus-bc')), 'The Fundamental Theorem of Calculus', 'fundamental-theorem-of-calculus', '[{"type":"meta","author":"SFMA Staff","frequency":"important"},{"type":"section","title":"Introduction"},{"type":"text","content":"The **Fundamental Theorem of Calculus** (FTC) ties together the two central operations of calculus — differentiation and integration — showing they are inverses of one another."},{"type":"section","title":"The Two Parts"},{"type":"text","content":"**Part 1.** If $F(x) = \\displaystyle\\int_a^x f(t)\\,dt$ with $f$ continuous, then $F$ is differentiable and\n$$F''(x) = f(x).$$\n\n**Part 2 (Evaluation).** If $F$ is any antiderivative of $f$ on $[a,b]$, then\n$$\\int_a^b f(x)\\,dx = F(b) - F(a).$$\n\nPart 2 turns the hard problem of summing infinitely many slices into the easy problem of evaluating an antiderivative at two endpoints."},{"type":"resource","source":"Paul''s Online Notes","stars":4,"title":"The Fundamental Theorem of Calculus","description":"A clear statement of both parts with fully worked examples.","url":"https://tutorial.math.lamar.edu/classes/calci/proofintegrals.aspx"},{"type":"section","title":"Practice Problems"},{"type":"problem","title":"A definite integral","source":"AP Calculus BC (practice)","difficulty":"Easy","statement":"Evaluate\n$$\\int_1^3 \\left(2x + 1\\right)\\,dx.$$","hint":"Find an antiderivative, then apply Part 2: $F(3) - F(1)$.","solution":"An antiderivative is $F(x) = x^2 + x$. Then\n$$F(3) - F(1) = (9 + 3) - (1 + 1) = 12 - 2 = 10.$$"},{"type":"problem","title":"Differentiating an integral","source":"AP Calculus BC (practice)","difficulty":"Medium","statement":"Let $\\displaystyle G(x) = \\int_0^{x^2} \\cos(t)\\,dt$. Find $G''(x)$.","hint":"Combine FTC Part 1 with the chain rule, since the upper limit is $x^2$.","solution":"By Part 1 with the chain rule,\n$$G''(x) = \\cos\\!\\left(x^2\\right)\\cdot \\frac{d}{dx}\\!\\left(x^2\\right) = 2x\\cos\\!\\left(x^2\\right).$$"},{"type":"problem","title":"Area under a curve","source":"AP Calculus BC (practice)","difficulty":"Hard","statement":"Find the area of the region bounded by $y = x^2$, the $x$-axis, and the lines $x = 0$ and $x = 2$.","hint":"Area equals $\\int_0^2 x^2\\,dx$.","solution":"The antiderivative of $x^2$ is $\\tfrac{x^3}{3}$, so\n$$\\int_0^2 x^2\\,dx = \\left[\\frac{x^3}{3}\\right]_0^2 = \\frac{8}{3} - 0 = \\frac{8}{3}.$$"}]'::jsonb, 0)
on conflict (module_id, slug) do update set
  title = excluded.title, content = excluded.content, order_index = excluded.order_index;

commit;
